mapper.select:
Select * from entrepreneurship_project  as ep join student_information as si on ep.student_number = si.student_number\


        AND ep.student_name LIKE CONCAT('%',#{studentName},'%')


        AND ep.student_number LIKE CONCAT('%',#{studentNumber},'%')


        and si.classes = #{classes}


        and si.grade = #{grade}


        and si.major = #{major}


        and si.college = #{college}
